<script setup lang="ts">
import { refreshFeedback as vRefreshFeedback } from '../../../shared/directives/refreshFeedback';
import { computed, defineAsyncComponent, nextTick, onUnmounted, ref, watch } from 'vue';
import { invoke } from '@tauri-apps/api/core';
import { Search, RefreshCw, Play, Pause, Database, ChevronLeft, ChevronRight } from '@lucide/vue';
import { discoveryAnalysisPrompt, type DiscoveryAnalysis } from '../discoveryAnalysis';
import { useI18n } from '../uiPorts';
import DiscoveryExclusions from './DiscoveryExclusions.vue';
import SeedReviewWorkbench from './SeedReviewWorkbench.vue';
import ContinuousDiscovery from './ContinuousDiscovery.vue';
const AutonomousProbeWorkbench=defineAsyncComponent(()=>import('./AutonomousProbeWorkbench.vue'));
const { tr } = useI18n();
const enrichmentRevision=ref(0);
async function scopeConfirmed(){if(advanced.value){const g=generation;await refreshProgress(g,true);if(g!==generation||disposed)return;rootsText.value=data.value?.roots.join('\n')||'';}emit('confirmed');emit('changed');}
function enriched(){enrichmentRevision.value++;void refreshProgress(generation,true);queueLocal();emit('changed');}
import HunterExpansionProgress, { type HunterExpansion } from './HunterExpansionProgress.vue';
const props=defineProps<{projectId?:number;review?:DiscoveryAnalysis;batchReview?:boolean;archived?:boolean}>();const emit=defineEmits<{changed:[];confirmed:[];collect:[];results:[];seeds:[];configure:[];analyze:[value:{analysis:DiscoveryAnalysis;prompt:string}]}>();
type Seed={id:number;host:string;source:string;reference:string;wildcard:boolean;eligible:boolean;queryEligible?:boolean;excluded?:boolean};
type Harvest={id:string;status:string;total:number;processed:number;skipped:number;added:number;certificates:number;reason:string;updatedAt:string};
type View={expansions?:HunterExpansion[];roots:string[];seeds:Seed[];seedTotal?:number;allSeeds?:number;seedPage?:number;seedPageSize?:number;harvest?:Harvest|null;settings:{keyConfigured:boolean;contractVerified:boolean;maxRequests:number;maxResults:number};requests?:{id:string;day:string;state:string;receipt:unknown}[];nextCursor?:number;batchRows?:number};
type LocalMatch={target:string;kind:string;matchCount:number;endpointMatches:number;certificateMatches:number;rawCertificateMatches:number;certificateCount:number;certificates:{fingerprint:string;domains:string[];assetIds:number[];eligible:boolean}[];assets:{id:number;host:string;matchType:string;certificatePresent:boolean}[];inspectionTruncated:boolean;certificatePreviewTruncated:boolean;harvest?:Harvest|null};
type ManualTool='scope'|'query'|'local'|'probe'|'enrichment'|'summary';
const advanced=ref(false),manualProbe=ref(false),moreOpen=ref(false),activeTool=ref<ManualTool>('query');
const toolOptions=computed<{key:ManualTool;label:string;hint:string}[]>(()=>[{key:'query',label:tr('补查一条线索','Look up a lead'),hint:tr('按域名、指纹或 CNAME 精确查找','Exact lookup by domain, fingerprint, or CNAME')},{key:'scope',label:tr('管理允许范围','Manage allowed scope'),hint:tr('手动维护已确认的域名','Maintain confirmed domains manually')},{key:'local',label:tr('维护本地线索','Maintain local leads'),hint:tr('检索、重新提取或排除线索','Search, re-extract, or exclude leads')},{key:'probe',label:tr('独立探测任务','Standalone probe task'),hint:tr('单独设置 Agent 探测任务','Set up an Agent probe task on its own')},{key:'enrichment',label:tr('补证高级选项','Advanced evidence enrichment'),hint:tr('独立调整补证并发和巡检间隔','Tune enrichment concurrency and check interval separately')},{key:'summary',label:tr('候选摘要与对话','Candidate summary and chat'),hint:tr('兼容旧版单次摘要分析','Legacy one-off summary analysis')}]);
const selectedTool=computed(()=>toolOptions.value.find(tool=>tool.key===activeTool.value));
function showMore(){if(moreOpen.value)closeAdvanced();else moreOpen.value=true;}
function collectManually(){if(props.archived)return;emit('collect');}

const data=ref<View>(),rootsText=ref(''),target=ref(''),hunterKind=ref('domain'),cursor=ref(0),busy=ref(false),reading=ref(false),error=ref(''),readError=ref(''),notice=ref(''),receipt=ref<unknown>();
type Admission={eligible:boolean;reason:string;anchor?:string};
const admission=ref<Admission>();
const seedSearch=ref(''),seedSource=ref('all'),seedPage=ref(1),localMatch=ref<LocalMatch>(),localLoading=ref(false),localError=ref('');
let generation=0,pageSequence=0,localSequence=0,disposed=false,pendingUntil=0;
let pollTimer:ReturnType<typeof setTimeout>|undefined,searchTimer:ReturnType<typeof setTimeout>|undefined,localTimer:ReturnType<typeof setTimeout>|undefined;
const harvesting=computed(()=>!!data.value?.harvest&&['running','stopping'].includes(data.value.harvest.status));
const harvestPercent=computed(()=>{const h=data.value?.harvest;return !h?0:h.status==='completed'?100:h.total?Math.min(100,Math.floor(h.processed/h.total*100)):0;});
const pageCount=computed(()=>Math.max(1,Math.ceil((data.value?.seedTotal??data.value?.seeds.length??0)/(data.value?.seedPageSize??50))));
const labels=computed<Record<string,string>>(()=>({running:tr('正在自动提取','Extracting automatically'),stopping:tr('正在暂停','Pausing'),paused:tr('已暂停','Paused'),interrupted:tr('已中断，可继续','Interrupted, can resume'),failed:tr('提取遇到问题，可继续','Extraction hit a problem, can resume'),completed:tr('本轮提取完成','Extraction round complete')}));
const sources=computed<Record<string,string>>(()=>({observed_host:tr('已收录主机','Recorded host'),certificate_name:tr('证书 CN / SAN','Certificate CN / SAN'),page:tr('已采集页面','Collected page'),certificate_domain:tr('证书域名','Certificate domain'),certificate_cn:tr('证书 CN','Certificate CN'),certificate_sha256:tr('证书 SHA-256','Certificate SHA-256'),cname:tr('测绘 CNAME','Mapped CNAME'),page_or_inline_script:tr('页面 / 内联脚本','Page / inline script'),certificate_transparency:tr('证书透明度','Certificate transparency'),dns_cname:'DNS CNAME',confirmed_scope:tr('已确认范围','Confirmed scope'),confirmed_review_name:tr('全项目审阅确认的域名','Domain confirmed in project-wide review')}));
const matchTypes=computed<Record<string,string>>(()=>({endpoint:tr('本地主机','Local host'),certificate_exact:tr('证书域名精确匹配','Exact certificate domain match'),certificate_wildcard:tr('通配证书覆盖，仅线索','Covered by wildcard certificate, lead only'),fingerprint:tr('证书指纹匹配','Certificate fingerprint match'),saved_lead:tr('已保存的历史线索','Saved historical lead')}));
function schedule(g=generation){clearTimeout(pollTimer);if(advanced.value&&!disposed&&g===generation&&(Date.now()<pendingUntil||harvesting.value||data.value?.expansions?.some(i=>['running','stopping'].includes(i.status))))pollTimer=setTimeout(()=>void refreshProgress(g),1500);}
async function readPage(g=generation){
 const projectId=props.projectId,seq=++pageSequence;if(!advanced.value||!projectId||disposed||g!==generation)return false;
 reading.value=true;
 try{const v=await invoke<View>('get_asset_discovery_page',{projectId,search:seedSearch.value,source:seedSource.value,page:seedPage.value});if(disposed||g!==generation||seq!==pageSequence)return false;
  const before=data.value?.harvest;data.value=v;seedPage.value=v.seedPage??seedPage.value;
  if(before&&before.status!=='completed'&&v.harvest?.id===before.id&&v.harvest.status==='completed'){notice.value=tr(`本轮已处理 ${v.harvest.processed.toLocaleString()} 条资产，新增 ${v.harvest.added.toLocaleString()} 条线索。没有联网或消耗积分。`,`Processed ${v.harvest.processed.toLocaleString()} assets this round and added ${v.harvest.added.toLocaleString()} new leads. No network requests were made and no credits were used.`);emit('changed');queueLocal();}
  readError.value='';return true;
 }catch(e){if(g===generation&&seq===pageSequence)readError.value=String(e);return false;}
 finally{if(g===generation&&seq===pageSequence)reading.value=false;}
}
async function refreshProgress(g=generation,force=false){if(force)pendingUntil=Date.now()+5000;const ok=await readPage(g);schedule(g);return ok;}
async function load(){const p=props.projectId,g=++generation;++localSequence;++pageSequence;clearTimeout(pollTimer);clearTimeout(searchTimer);clearTimeout(localTimer);data.value=undefined;error.value='';readError.value='';localMatch.value=undefined;admission.value=undefined;localError.value='';localLoading.value=false;cursor.value=0;rootsText.value='';target.value='';hunterKind.value='domain';receipt.value=undefined;notice.value='';seedSearch.value='';seedSource.value='all';seedPage.value=1;busy.value=false;reading.value=false;if(!p)return;busy.value=true;try{await readPage(g);if(disposed||g!==generation)return;const loaded=data.value as View|undefined;rootsText.value=loaded?.roots.join('\n')||'';target.value=loaded?.roots[0]||'';schedule(g);}finally{if(g===generation)busy.value=false;}}
async function changePage(page:number){if(reading.value)return;const before=seedPage.value,g=generation;seedPage.value=Math.max(1,Math.min(pageCount.value,page));error.value='';if(!await refreshProgress(g)&&g===generation)seedPage.value=before;}
function searchSeeds(){clearTimeout(searchTimer);seedPage.value=1;const g=generation;searchTimer=setTimeout(()=>void refreshProgress(g),300);}
function queueLocal(){clearTimeout(localTimer);++localSequence;localMatch.value=undefined;admission.value=undefined;localError.value='';localLoading.value=advanced.value&&activeTool.value==='query'&&!!target.value.trim()&&!!props.projectId;if(!localLoading.value)return;const g=generation;localTimer=setTimeout(()=>void checkLocal(g),400);}
async function checkLocal(g=generation){clearTimeout(localTimer);const projectId=props.projectId,value=target.value.trim(),seq=++localSequence;if(!advanced.value||activeTool.value!=='query'||!projectId||!value||disposed||g!==generation)return;localLoading.value=true;localError.value='';try{const [result,preview]=await Promise.all([invoke<LocalMatch>('lookup_local_discovery',{projectId,target:value}),invoke<Admission>('preview_hunter_evidence',{input:{projectId,target:value,kind:hunterKind.value}})]);if(disposed||g!==generation||seq!==localSequence)return;localMatch.value=result;admission.value=preview;}catch(e){if(g===generation&&seq===localSequence)localError.value=String(e);}finally{if(g===generation&&seq===localSequence)localLoading.value=false;}}
async function startHarvest(){const projectId=props.projectId,g=generation;if(!projectId||props.archived||busy.value||harvesting.value)return;busy.value=true;error.value='';try{const h=await invoke<Harvest>('start_asset_discovery_harvest',{projectId});if(disposed||g!==generation)return;if(data.value)data.value.harvest=h;notice.value=tr('本地提取已启动，后台会自动处理本轮全部资产，可随时暂停。','Local extraction started. All assets in this round are processed in the background, and you can pause at any time.');pendingUntil=Date.now()+5000;schedule(g);}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
async function pauseHarvest(){const projectId=props.projectId,id=data.value?.harvest?.id,g=generation;if(!projectId||props.archived||!id||busy.value||!harvesting.value)return;busy.value=true;error.value='';try{const h=await invoke<Harvest>('pause_asset_discovery_harvest',{projectId,runId:id});if(disposed||g!==generation)return;if(data.value)data.value.harvest=h;schedule(g);}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
async function startHunter(){const projectId=props.projectId,g=generation;if(!projectId||props.archived||busy.value||!target.value||!data.value?.settings.keyConfigured||!data.value.settings.contractVerified)return;busy.value=true;error.value='';notice.value='';try{const input={projectId,kind:hunterKind.value,target:target.value.trim()};const preview=await invoke<Admission>('preview_hunter_evidence',{input});if(disposed||g!==generation)return;admission.value=preview;if(!preview.eligible){error.value=preview.reason;return;}await invoke('start_hunter_expansion',{input});if(disposed||g!==generation)return;notice.value=tr('已启动精确关联自动分页，可使用免费与权益积分，不设积分预算；每页保存回执，可随时暂停。','Exact-match auto-pagination started. Free and plan credits may be used with no credit budget; a receipt is saved for every page, and you can pause at any time.');await refreshProgress(g,true);}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
async function act(action:string,h=target.value){if(action==='hunter'){await startHunter();return;}if(action==='harvest'){await startHarvest();return;}const p=props.projectId,g=generation;if(!p||props.archived||busy.value)return;busy.value=true;error.value='';notice.value='';try{await invoke('act_asset_discovery',{input:{projectId:p,action,roots:rootsText.value.split(/[\s,;]+/).filter(Boolean),host:h,hunterKind:hunterKind.value,cursor:0,requestId:crypto.randomUUID()}});if(disposed||g!==generation)return;await readPage(g);if(disposed||g!==generation)return;if(action==='scopes'){rootsText.value=data.value?.roots.join('\n')||'';queueLocal();notice.value=tr('当前项目的确认范围已保存。','Confirmed scope for this project saved.');}else notice.value=action==='promote'?tr('已加入下一次 FOFA 查询的域名种子，没有立即启动采集。','Added as a domain seed for the next FOFA query; no collection was started yet.'):tr('线索已保存；发现来源不等于归属确认。','Lead saved. A discovery source does not confirm ownership.');}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
const reviewPanel=ref<HTMLElement>();
const organization=ref(''),analysis=ref<DiscoveryAnalysis>(),analyzing=ref(false),selectedCandidates=ref<string[]>([]),confirmedRelationship=ref(false);
async function analyzeSeeds(){
 const projectId=props.projectId,g=generation;if(!projectId||props.archived||analyzing.value||busy.value)return;
 analyzing.value=true;error.value='';
 try{const report=await invoke<DiscoveryAnalysis>('analyze_local_discovery',{projectId,organization:organization.value.trim()});if(disposed||g!==generation||projectId!==props.projectId)return;
 analysis.value=report;selectedCandidates.value=[];confirmedRelationship.value=false;emit('analyze',{analysis:report,prompt:discoveryAnalysisPrompt(report)});
 }catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)analyzing.value=false;}
}
async function confirmCandidates(){
 const report=analysis.value,projectId=props.projectId,g=generation;if(!report||props.archived||report.projectId!==projectId||!confirmedRelationship.value||!selectedCandidates.value.length||busy.value)return;
 busy.value=true;error.value='';
 try{await invoke('confirm_local_discovery',{input:{projectId,organization:report.organization,hosts:[...selectedCandidates.value],expectedRoots:report.roots,userConfirmed:true}});if(disposed||g!==generation)return;
 await readPage(g);if(disposed||g!==generation)return;rootsText.value=data.value?.roots.join('\n')||'';analysis.value=undefined;selectedCandidates.value=[];confirmedRelationship.value=false;notice.value=tr('已保存人工确认的域名范围；尚未启动采集、探测或 Hunter。','Manually confirmed domain scope saved. No collection, probe, or Hunter query has been started.');emit('confirmed');emit('changed');
 }catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}
}
function applyReview(){const report=props.review;if(report&&report.projectId===props.projectId){organization.value=report.organization;analysis.value=report;selectedCandidates.value=[];confirmedRelationship.value=false;void nextTick(()=>reviewPanel.value?.scrollIntoView?.({block:'start',behavior:'smooth'}));}}
async function openAdvanced(tool:ManualTool='query'){
 const wasOpen=advanced.value;moreOpen.value=true;advanced.value=true;activeTool.value=tool;manualProbe.value=tool==='probe';
 if(!wasOpen||!data.value){if(!['enrichment','probe'].includes(tool))await load();}
 if(advanced.value&&!disposed&&tool==='summary')applyReview();
 if(tool==='query')queueLocal();else{clearTimeout(localTimer);++localSequence;localLoading.value=false;}
}
function closeAdvanced(){advanced.value=false;manualProbe.value=false;moreOpen.value=false;++generation;++localSequence;++pageSequence;clearTimeout(pollTimer);clearTimeout(searchTimer);clearTimeout(localTimer);busy.value=false;reading.value=false;localLoading.value=false;}
watch(()=>props.review,report=>{if(report&&report.projectId===props.projectId){if(advanced.value){activeTool.value='summary';applyReview();}else void openAdvanced('summary');}});
watch(organization,value=>{if(analysis.value&&analysis.value.organization!==value.trim()){analysis.value=undefined;selectedCandidates.value=[];confirmedRelationship.value=false;}});
function localTime(value:string){const parsed=new Date(/Z$|[+-]\d\d:\d\d$/.test(value)?value:value.replace(' ','T')+'Z');return Number.isNaN(parsed.getTime())?value:parsed.toLocaleString('zh-CN',{hour12:false});}
function selectSeed(seed:Seed){activeTool.value='query';target.value=seed.host;hunterKind.value=seed.source==='certificate_sha256'?'fingerprint':seed.source.includes('cname')?'cname':'domain';}
function useFingerprint(value:string){target.value=value;hunterKind.value='fingerprint';}
watch([target,hunterKind],queueLocal);
watch(()=>props.projectId,()=>{analysis.value=undefined;organization.value='';analyzing.value=false;selectedCandidates.value=[];confirmedRelationship.value=false;closeAdvanced();data.value=undefined;rootsText.value='';target.value='';if(props.review?.projectId===props.projectId)void openAdvanced('summary');},{immediate:true});
onUnmounted(()=>{disposed=true;++generation;++localSequence;++pageSequence;clearTimeout(pollTimer);clearTimeout(searchTimer);clearTimeout(localTimer);});
</script>
<template>
<section class="discovery-workbench" data-testid="asset-discovery-workbench">
 <p v-if="!projectId" class="discovery-empty">{{tr('请先选择工作空间。','Select a workspace first.')}}</p>
 <template v-else>
  <SeedReviewWorkbench :refresh-version="enrichmentRevision" :project-id="projectId" :archived="archived" @collect="collectManually" @configure="emit('configure')" @results="emit('results')" @confirmed="scopeConfirmed"/>
  <nav class="discovery-secondary" :aria-label="tr('发现记录与其他操作','Discovery records and other actions')">
   <button class="text-button" data-discovery-action="seeds" @click="emit('seeds')">{{tr('项目种子与历史','Project seeds and history')}}</button>
   <button class="text-button" data-discovery-action="more" :aria-expanded="moreOpen" @click="showMore">{{moreOpen?tr('收起更多操作','Fewer actions'):tr('更多操作','More actions')}}</button>
  </nav>
  <section v-if="moreOpen" class="discovery-more" :aria-label="tr('更多发现操作','More discovery actions')">
   <p class="helper">{{tr('常规采集、提炼和补证由上方自动接续。只在需要指定条件或维护数据时使用以下工具。','Routine collection, refinement, and evidence enrichment continue automatically above. Use the tools below only when you need specific conditions or data maintenance.')}}</p>
   <div class="discovery-tool-menu">
    <button class="discovery-tool-option" data-discovery-action="collect" :disabled="archived" @click="collectManually"><strong>{{tr('自定义 FOFA 采集','Custom FOFA collection')}}</strong><small>{{tr('指定查询目标，启动独立采集任务','Set a query target and start a standalone collection job')}}</small></button>
    <button v-for="tool in toolOptions" :key="tool.key" class="discovery-tool-option" :class="{selected:advanced&&activeTool===tool.key}" :data-discovery-tool="tool.key" :disabled="archived&&['probe','enrichment','summary'].includes(tool.key)" @click="openAdvanced(tool.key)"><strong>{{tool.label}}</strong><small>{{tool.hint}}</small></button>
   </div>
   <section v-if="advanced" class="discovery-selected-tool" :data-active-discovery-tool="activeTool">
    <header class="discovery-heading"><div><h3>{{selectedTool?.label}}</h3><p>{{selectedTool?.hint}}</p></div><div class="discovery-header-actions"><button class="button ghost compact" data-discovery-action="return" @click="closeAdvanced">{{tr('收起工具','Close tool')}}</button><button v-if="!['enrichment','probe'].includes(activeTool)" v-refresh-feedback="{scope:projectId,busy:reading,error:readError}" class="button ghost compact" :disabled="busy||reading" @click="refreshProgress(generation,true)"><RefreshCw :size="14"/>{{tr('刷新','Refresh')}}</button></div></header>
    <p v-if="archived" class="helper">{{tr('此项目已归档，仅可查看历史记录；恢复项目后可继续采集和发现。','This project is archived, so only its history can be viewed. Restore the project to continue collection and discovery.')}}</p>
    <template v-if="activeTool==='scope'"><section class="discovery-block"><h4><span class="step-number">1</span>{{tr('确认域名范围','Confirm domain scope')}}</h4><p class="helper">{{tr('每行一个域名；共享平台请限定到你的具体租户。','One domain per line. For shared platforms, limit it to your own tenant.')}}</p><label class="field"><span class="sr-label">{{tr('明确确认的域名范围','Explicitly confirmed domain scope')}}</span><textarea v-model="rootsText" rows="3" :disabled="archived||busy" placeholder="example.com"/></label><footer><button class="button secondary compact" :disabled="archived||busy" @click="act('scopes')">{{tr('保存确认范围','Save confirmed scope')}}</button><span class="muted">{{tr(`已保存 ${data?.roots.length??0} 个范围`,`Saved scopes: ${data?.roots.length??0}`)}}</span></footer></section></template>
    <template v-else-if="activeTool==='local'"><section class="discovery-block harvest-block"><h4><span class="step-number">2</span>{{tr('自动整理本地线索','Organize local leads automatically')}}</h4><p class="helper">{{tr('整理本地观察记录，后台自动分批执行。提取数量不等于目标资产数，也不会自动送入 Hunter。','Organizes local observation records in automatic background batches. The extracted count is not the number of target assets, and nothing is sent to Hunter automatically.')}}</p><div v-if="data?.harvest" class="harvest-progress" role="status"><div><strong>{{labels[data.harvest.status]||data.harvest.status}}</strong><span>{{tr(`${data.harvest.processed.toLocaleString()} / ${data.harvest.total.toLocaleString()} 条`,`${data.harvest.processed.toLocaleString()} / ${data.harvest.total.toLocaleString()} assets`)}}</span></div><progress :value="harvestPercent" max="100" :aria-label="tr(`本地提取进度 ${harvestPercent}%`,`Local extraction progress ${harvestPercent}%`)"/><p>{{tr(`新增 ${data.harvest.added.toLocaleString()} 条线索 · 有证书字段 ${data.harvest.certificates.toLocaleString()} 条资产（尚非证书准入数量）`,`${data.harvest.added.toLocaleString()} new leads · ${data.harvest.certificates.toLocaleString()} assets with certificate fields (not yet the certificate admission count)`)}}<span v-if="data.harvest.skipped"> · {{tr(`已移除 / 不可读 ${data.harvest.skipped} 条`,`${data.harvest.skipped} removed / unreadable`)}}</span></p><small>{{data.harvest.reason}}</small><small class="harvest-updated">{{tr(`更新于 ${localTime(data.harvest.updatedAt)} · 本轮资产快照，新入库资产可重新提取`,`Updated ${localTime(data.harvest.updatedAt)} · Snapshot of this round's assets; re-extract to include newly added assets`)}}</small></div><div v-else class="harvest-empty"><Database :size="22"/><span>{{tr('提取主机、证书、CNAME 和已采集页面中的域名','Extracts domains from hosts, certificates, CNAMEs, and collected pages')}}</span></div><footer><button v-if="!harvesting" class="button primary compact" :disabled="archived||busy" data-discovery-action="harvest" @click="startHarvest"><Play :size="14"/>{{data?.harvest&&data.harvest.status!=='completed'?tr('继续本地提取','Continue local extraction'):data?.harvest?.status==='completed'?tr('重新提取全部资产','Re-extract all assets'):tr('一键提取全部资产','Extract all assets')}}</button><button v-else class="button danger compact" :disabled="archived||busy||data?.harvest?.status==='stopping'" data-discovery-action="pause-harvest" @click="pauseHarvest"><Pause :size="14"/>{{data?.harvest?.status==='stopping'?tr('正在暂停…','Pausing…'):tr('暂停提取','Pause extraction')}}</button><span class="local-only">{{tr('仅整理本地 · 不查询 Hunter','Local only · No Hunter queries')}}</span></footer></section><section class="discovery-block seed-directory"><header><h4>{{seedSource==='excluded'?tr('已排除线索','Excluded leads'):tr('可用线索库','Available leads')}} <span class="seed-count">{{(seedSource==='excluded'?(data?.seedTotal??0):(data?.allSeeds??data?.seeds.length??0)).toLocaleString()}}</span></h4><span class="muted">{{tr('按来源筛选，搜索全部已提取线索','Filter by source and search all extracted leads')}}</span></header><div class="seed-search-controls"><label class="seed-search"><Search :size="15"/><input v-model="seedSearch" :placeholder="tr('搜索域名、CNAME 或证书指纹','Search domains, CNAMEs, or certificate fingerprints')" @input="searchSeeds"/></label><select v-model="seedSource" :aria-label="tr('线索来源分类','Lead source category')" @change="searchSeeds"><option value="all">{{tr('全部来源','All sources')}}</option><option value="certificate">{{tr('证书与 CT','Certificates and CT')}}</option><option value="cname">CNAME</option><option value="host">{{tr('已收录主机','Recorded hosts')}}</option><option value="page">{{tr('页面与脚本','Pages and scripts')}}</option><option value="excluded">{{tr('已排除线索','Excluded leads')}}</option></select></div><DiscoveryExclusions v-if="!archived" :project-id="projectId" :suggested-domain="seedSearch" @changed="refreshProgress(generation,true);queueLocal();emit('changed')"/><div class="seed-scroll" :aria-busy="reading"><table v-if="data?.seeds.length"><thead><tr><th>{{tr('线索','Lead')}}</th><th>{{tr('发现依据','Discovery basis')}}</th><th>{{tr('使用状态','Status')}}</th><th></th></tr></thead><tbody><tr v-for="seed in data.seeds" :key="seed.id"><td><code>{{seed.wildcard?'*.':''}}{{seed.host}}</code></td><td><span>{{sources[seed.source]||seed.source}}</span><small :title="seed.reference">{{seed.reference}}</small></td><td><span class="seed-state" :class="{'seed-eligible':seed.eligible||seed.queryEligible}">{{seed.excluded?tr('已排除 · 不参与补查','Excluded · Not used for lookups'):seed.wildcard?tr('通配符范围，非已发现主机','Wildcard scope, not a discovered host'):seed.eligible?tr('已在确认范围内','In confirmed scope'):seed.queryEligible?tr('可精确关联，归属待核验','Exact match available, ownership unverified'):tr('外部线索，待确认','External lead, unconfirmed')}}</span></td><td><button class="button ghost compact" :disabled="archived||busy||seed.excluded||!(seed.eligible||seed.queryEligible)||seed.wildcard" @click="selectSeed(seed)">{{tr('选择','Select')}}</button></td></tr></tbody></table><p v-else class="discovery-empty">{{reading?tr('正在读取线索…','Loading leads…'):seedSearch||seedSource!=='all'?tr('没有匹配的线索，请调整搜索或分类。','No matching leads. Adjust the search or category.'):tr('尚无线索，先一键提取全部本地资产。','No leads yet. Extract all local assets first.')}}</p></div><footer class="seed-pagination"><span>{{tr(`匹配 ${(data?.seedTotal??data?.seeds.length??0).toLocaleString()} 条 · 第 ${data?.seedPage??seedPage} / ${pageCount} 页`,`${(data?.seedTotal??data?.seeds.length??0).toLocaleString()} matches · Page ${data?.seedPage??seedPage} of ${pageCount}`)}}</span><div><button class="button ghost compact" :disabled="reading||seedPage<=1" :aria-label="tr('上一页线索','Previous page of leads')" @click="changePage(seedPage-1)"><ChevronLeft :size="15"/></button><button class="button ghost compact" :disabled="reading||seedPage>=pageCount" :aria-label="tr('下一页线索','Next page of leads')" @click="changePage(seedPage+1)"><ChevronRight :size="15"/></button></div></footer></section>
</template>
    <template v-else-if="activeTool==='query'"><section class="discovery-block query-block"><h4><span class="step-number">3</span>{{tr('先查本地，再精确补查','Check locally, then run an exact lookup')}}</h4><div class="discovery-query-fields"><label class="field"><span>{{tr('域名 / 证书 SHA-256 / CNAME 目标','Domain / certificate SHA-256 / CNAME target')}}</span><input v-model="target" :disabled="archived||busy" :placeholder="tr('输入域名，自动检查本地资产和证书','Enter a domain to check local assets and certificates automatically')" autocomplete="off"/></label><label class="field"><span>{{tr('Hunter 补查依据','Hunter lookup basis')}}</span><select v-model="hunterKind" :disabled="archived||busy"><option value="domain">{{tr('精确域名（仅此主机名）','Exact domain (this hostname only)')}}</option><option value="domain_tree">{{tr('已确认域名树（根域和子域）','Confirmed domain tree (root and subdomains)')}}</option><option value="fingerprint">{{tr('证书 SHA-256 精确指纹','Exact certificate SHA-256 fingerprint')}}</option><option value="cname">{{tr('CNAME 精确目标','Exact CNAME target')}}</option></select></label></div>
<div v-if="target.trim()" class="local-match-panel" :aria-busy="localLoading"><p v-if="localLoading" role="status">{{tr('正在核对本地记录，不会联网…','Checking local records without network access…')}}</p><p v-else-if="localError" role="alert">{{localError}}</p><template v-else-if="localMatch"><div class="local-match-heading"><strong>{{localMatch.certificateMatches?(localMatch.certificateCount?tr('本地已有证书信息，可选择已保存指纹','Certificate data found locally; choose a saved fingerprint'):tr('本地已有证书信息，缺少可用指纹','Certificate data found locally, but no usable fingerprint')):localMatch.endpointMatches?tr('本地已有资产，尚未发现证书信息','Asset found locally, no certificate data yet'):localMatch.matchCount?tr('本地已有相关历史线索','Related historical leads found locally'):tr('暂未发现本地匹配记录','No local matches found')}}</strong><span class="local-only">{{tr('未发出外部请求','No external requests sent')}}</span></div><p>{{tr(`匹配 ${localMatch.matchCount} 条本地资产 / 关联记录 · ${localMatch.certificateCount} 个已保存指纹`,`${localMatch.matchCount} local assets / related records matched · ${localMatch.certificateCount} saved fingerprints`)}}<span v-if="localMatch.inspectionTruncated">{{tr('（仅预览前 200 条，不能据此排除后续记录）',' (only the first 200 are previewed, so later records cannot be ruled out)')}}</span></p><p v-if="localMatch.harvest?.status!=='completed'" class="local-caution">{{harvesting?tr('本地全量提取正在进行，剩余证书线索会继续补充；完成后自动重新核对。','Full local extraction is running and will keep adding certificate leads; the check reruns automatically when it finishes.'):data?.harvest?tr('本地全量提取尚未完成，可继续本地提取后核对证书。','Full local extraction is not finished. Continue local extraction, then check certificates.'):tr('本地全量提取尚未完成，IP 资产中的证书域名可能还未进入索引；可先点击“一键提取全部资产”。','Full local extraction is not finished, so certificate domains from IP assets may not be indexed yet. Click “Extract all assets” first.')}}</p><p v-if="localMatch.harvest?.status==='completed'&&!localMatch.matchCount" class="local-caution">{{tr(`最近一次提取更新于 ${localTime(localMatch.harvest.updatedAt)}；若有新入库资产，可重新提取后再核对。`,`Last extraction updated ${localTime(localMatch.harvest.updatedAt)}. If new assets were added since, re-extract and check again.`)}}</p><p v-if="localMatch.certificateMatches&&!localMatch.certificateCount" class="local-caution">{{tr('已有证书内容或域名信息，但没有可用 SHA-256 指纹；不会用域名冒充指纹。','Certificate content or domain data exists, but there is no usable SHA-256 fingerprint. A domain is never used in place of a fingerprint.')}}</p><div v-if="localMatch.certificates.length" class="local-certificates"><article v-for="cert in localMatch.certificates" :key="cert.fingerprint"><div><span>{{tr(`SHA-256 · 本地资产 #${cert.assetIds.slice(0,3).join('、')}`,`SHA-256 · Local asset #${cert.assetIds.slice(0,3).join(', ')}`)}}</span><code>{{cert.fingerprint}}</code><small v-if="cert.domains.length">{{cert.domains.slice(0,5).join(tr('、',', '))}}</small><small v-if="!cert.eligible" class="local-caution">{{tr('需先完成本地提取，并确认该证书关联的域名范围。','Finish local extraction and confirm the domain scope tied to this certificate first.')}}</small></div><button class="button secondary compact" :disabled="archived||busy||!cert.eligible" @click="useFingerprint(cert.fingerprint)">{{tr('使用此指纹','Use this fingerprint')}}</button></article><p v-if="localMatch.certificatePreviewTruncated">{{tr('仅展示前 20 个不同指纹，请使用下方证书分类继续搜索。','Showing only the first 20 distinct fingerprints. Use the certificate category below to keep searching.')}}</p></div><details v-if="localMatch.assets.length"><summary>{{tr('查看本地匹配依据','View local match basis')}}</summary><ul><li v-for="asset in localMatch.assets" :key="asset.id"><span>#{{asset.id}} · {{asset.host}}</span><small>{{matchTypes[asset.matchType]||asset.matchType}}</small></li></ul></details><p class="local-match-note">{{tr('本地存在记录不等于当前存活或归属已确认；通配证书覆盖也不表示该主机已发现。','A local record does not mean the host is live now or that ownership is confirmed. Wildcard certificate coverage does not mean the host has been discovered.')}}</p></template></div>
<div class="query-actions-group"><div><button class="button secondary compact" :disabled="archived||busy||!target||hunterKind==='fingerprint'" @click="act('promote')">{{tr('加入 FOFA 查询种子','Add to FOFA query seeds')}}</button><button class="button ghost compact" :disabled="archived||busy||!target||hunterKind==='fingerprint'" @click="act('ct')">{{tr('CT 域名线索','CT domain leads')}}</button><button class="button ghost compact" :disabled="archived||busy||!target||hunterKind==='fingerprint'" @click="act('dns')">DNS / CNAME</button></div><button class="button primary compact" :disabled="archived||busy||localLoading||!target||!admission?.eligible||!data?.settings.keyConfigured||!data?.settings.contractVerified" @click="act('hunter')">{{data?.settings.contractVerified?tr('Hunter 精确关联 · 自动翻页','Hunter exact match · Auto-paginate'):tr('Hunter 补查（接口待核实）','Hunter lookup (API unverified)')}}</button></div><p v-if="admission" class="helper" role="status">{{tr(`付费补查检查：${admission.eligible?'已通过':'暂不允许'} · ${admission.reason}`,`Paid lookup check: ${admission.eligible?'passed':'not allowed yet'} · ${admission.reason}`)}}</p><p class="helper">{{tr('域名补查须在确认范围内；证书补查还须核对同一张证书的指纹与域名。无关 / 混合范围证书、无域名依据的指纹及范围外共享 CNAME 不自动查询；证书匹配仍不等于归属确认。','Domain lookups must be within the confirmed scope; certificate lookups must also match the fingerprint and domains of the same certificate. Unrelated or mixed-scope certificates, fingerprints with no domain basis, and shared CNAMEs outside the scope are not queried automatically. A certificate match still does not confirm ownership.')}}</p><p v-if="data&&!data.settings.contractVerified" class="helper">{{tr('Hunter 实际查询暂未启用，不会发送付费请求。','Live Hunter queries are not enabled yet, so no paid requests are sent.')}}</p><p v-else-if="data&&!data.settings.keyConfigured" class="helper">{{tr('请先在「配置中心 → 资产 API」保存并验证 Hunter API Key。','Save and verify the Hunter API key in “Settings → Asset APIs” first.')}}</p><details class="query-explanation"><summary>{{tr('查询范围、积分与数据使用说明','Query scope, credits, and data usage')}}</summary><p>{{tr('CT 将本次域名提交给 crt.sh；DNS 使用 Google Public DNS。Hunter 核验线索来源后，遍历近 30 天的全部可用分页，去重合并并显示每页及累计积分消耗。可使用免费与权益积分，不设积分预算；平台限制、额度耗尽或结果未知时暂停，不自动重发。页面与脚本线索只从已采集数据提取，不执行脚本。发现来源不等于归属确认，同一张证书的 CN / SAN 用于本地核验，不会因此单独追加 Hunter 查询。同条件、同时间窗口复用查询记录；SHA-256 和 CNAME 属于不同查询，可能再次命中同一批资产。本地去重不代表平台退还重复结果的积分。','CT submits this domain to crt.sh; DNS uses Google Public DNS. After verifying the lead source, Hunter walks every available page from the last 30 days, deduplicates and merges the results, and shows per-page and cumulative credit usage. Free and plan credits may be used with no credit budget; it pauses on platform limits, exhausted quota, or unknown results and never resends automatically. Page and script leads are extracted only from collected data; scripts are never executed. A discovery source does not confirm ownership; the CN / SAN of the same certificate is used for local verification and does not trigger a separate Hunter query. Queries with the same conditions and time window reuse earlier records; SHA-256 and CNAME are separate queries and may hit the same assets again. Local deduplication does not mean the platform refunds credits for duplicate results.')}}</p></details></section>
<HunterExpansionProgress v-if="!archived" :project-id="projectId" :items="data?.expansions" @changed="refreshProgress(generation,true)"/><details v-if="data?.requests?.length" class="query-explanation"><summary>{{tr('历史 Hunter 请求回执','Past Hunter request receipts')}}</summary><pre>{{JSON.stringify(data.requests,null,2)}}</pre></details>
</template>
    <ContinuousDiscovery v-else-if="activeTool==='enrichment'&&!archived" :project-id="projectId" :refresh-version="data?.roots?.join(',')" @changed="enriched"/>
    <AutonomousProbeWorkbench v-else-if="manualProbe&&!archived" :project-id="projectId" :archived="archived" @changed="enriched"/>
    <template v-else-if="activeTool==='summary'&&!archived"><details :open="!batchReview" class="discovery-legacy-analysis"><summary>{{tr('在对话中讨论单次候选摘要（不代替全量 AI 审阅）','Discuss a one-off candidate summary in chat (does not replace the full AI review)')}}</summary>
<section class="discovery-block seed-ai-entry"><h4>{{tr('AI 提炼项目种子','Refine project seeds with AI')}}</h4><p class="helper">{{tr('全量读取本地非回收资产，整理主机、证书和 CNAME 的观察摘要；转到对话草稿，由你发送给模型分析。归属和范围由你确认，确认前不会自动进入 Hunter。','Reads every local asset outside the trash and summarizes what was observed for hosts, certificates, and CNAMEs into a chat draft that you send to the model. You confirm ownership and scope; nothing goes to Hunter before you confirm.')}}</p><div class="seed-ai-controls"><label class="field"><span>{{tr('相关单位或域名关键词（可选，可填写多个）','Related organization or domain keywords (optional, multiple allowed)')}}</span><input v-model="organization" maxlength="240" :placeholder="tr('例如：中国移动 中移，或 10086.cn','e.g. China Mobile CMCC, or 10086.cn')" :disabled="analyzing||busy||archived"/></label><button class="button primary" :disabled="analyzing||busy||archived" data-discovery-action="analyze" @click="analyzeSeeds">{{analyzing?tr('正在全量整理本地摘要…','Summarizing all local data…'):tr('AI 提炼 · 前往对话','Refine with AI · Open chat')}}</button></div><small class="muted">{{tr('发送聊天时会将候选摘要交给当前模型；聊天授权沿用现有规则。','Sending the chat passes the candidate summary to the current model; existing chat authorization rules apply.')}}</small></section></details>
<section v-if="analysis" ref="reviewPanel" class="discovery-block seed-review" data-testid="discovery-seed-review"><h4>{{tr('核对候选并确认范围','Review candidates and confirm scope')}}</h4><p>{{tr(`已遍历 ${analysis.scannedAssets.toLocaleString()} 条本地资产；匹配 ${analysis.matchedAssets.toLocaleString()} 条，发现 ${analysis.candidateTotal.toLocaleString()} 个候选域名。`,`Scanned ${analysis.scannedAssets.toLocaleString()} local assets: ${analysis.matchedAssets.toLocaleString()} matched, ${analysis.candidateTotal.toLocaleString()} candidate domains found.`)}}{{analysis.previewTruncated?tr('仅展示前 80 项，可缩小单位或域名关键词重新分析。',' Showing only the first 80. Narrow the organization or domain keywords and analyze again.'):''}}</p><p class="helper">{{tr('以下是带本地来源的候选，不是 AI 已确认的资产。证书、CNAME、单位共现仍可能属于第三方；未勾选的域名不会加入范围。','These are candidates backed by local sources, not assets confirmed by AI. Certificates, CNAMEs, and organization co-occurrence may still belong to third parties; unchecked domains are not added to the scope.')}}</p><div class="seed-review-list"><label v-for="candidate in analysis.candidates" :key="candidate.host"><input v-model="selectedCandidates" type="checkbox" :value="candidate.host" :disabled="archived||busy||candidate.inConfirmedScope"/><span><strong>{{candidate.host}}</strong><small>{{candidate.inConfirmedScope?tr('已在确认范围 · ','In confirmed scope · '):''}}{{tr(`${candidate.assetCount} 条资产`,`${candidate.assetCount} assets`)}} · {{candidate.sources.map(source=>sources[source]||source).join(' / ')}} · #{{candidate.assetIds.join(tr('、',', '))}}</small><small>{{candidate.companies.join(tr('、',', '))||tr('没有单位归属证据','No organization ownership evidence')}}</small></span></label></div><label class="seed-confirm-relationship"><input v-model="confirmedRelationship" type="checkbox" :disabled="archived||busy"/>{{tr('我已核对，确认勾选的域名及其子域与目标单位相关，并允许加入后续探测范围。','I have reviewed and confirm that the selected domains and their subdomains are related to the target organization, and allow them to be added to the later probe scope.')}}</label><button class="button primary compact" :disabled="archived||busy||!confirmedRelationship||!selectedCandidates.length" @click="confirmCandidates">{{tr(`确认加入范围 · ${selectedCandidates.length} 项`,`Add to scope · ${selectedCandidates.length} selected`)}}</button><p class="helper">{{tr('仅保存范围；没有启动 Hunter、探测或赋予正式资产归属。凭证、证书证据和共享目标准入仍单独校验。','Saves the scope only. No Hunter query or probe is started, and no formal asset ownership is granted. Credentials, certificate evidence, and shared-target admission are still checked separately.')}}</p></section>
</template>
    <p v-if="busy" role="status" class="discovery-notice">{{tr('正在处理，请勿重复点击…','Processing… Please do not click again.')}}</p><p v-if="notice" role="status" class="discovery-notice">{{notice}}</p><p v-if="error||readError" role="alert" class="form-error">{{error||readError}}</p>
   </section>
  </section>
 </template>
</section>
</template>
